#!/usr/bin/env python3
import json
import time
import urllib.request
import websocket

def get_targets():
    return json.loads(urllib.request.urlopen("http://localhost:1337/json").read())

def new_tab(url):
    return json.loads(urllib.request.urlopen(f"http://localhost:1337/json/new?{url}").read())

def send(ws, mid, method, params=None):
    msg = {"id": mid, "method": method}
    if params:
        msg["params"] = params
    ws.send(json.dumps(msg))
    while True:
        resp = json.loads(ws.recv())
        if resp.get("id") == mid:
            return resp

# Open settings/security page in a new tab
tab = new_tab("chrome://settings/security")
print("Opened tab:", tab["id"], tab.get("url"))
ws_url = tab["webSocketDebuggerUrl"]
ws = websocket.create_connection(ws_url)

# Enable necessary domains
send(ws, 1, "Page.enable")
send(ws, 2, "Runtime.enable")

# Wait for page to finish loading
time.sleep(3)

# Try to click Standard Protection radio via JS
js = r"""
(function() {
  function findRadio(label) {
    const root = document.querySelector('settings-ui');
    if (!root) return null;
    function dig(node) {
      const found = [];
      const all = node.querySelectorAll ? node.querySelectorAll('*') : [];
      for (const el of all) {
        if (el.shadowRoot) found.push(...dig(el.shadowRoot));
        if (el.tagName && el.tagName.toLowerCase() === 'controlled-radio-button' ||
            (el.tagName && el.tagName.toLowerCase() === 'cr-radio-button')) {
          found.push(el);
        }
      }
      return found;
    }
    const radios = dig(root);
    for (const r of radios) {
      const name = r.getAttribute('name') || '';
      if (name.includes(label)) return r;
    }
    return null;
  }
  // For Standard Protection, the name is usually "standard"
  const r = findRadio('standard');
  if (r) {
    r.click();
    return 'clicked: ' + (r.getAttribute('name') || r.outerHTML.slice(0,200));
  }
  return 'not found';
})();
"""
res = send(ws, 3, "Runtime.evaluate", {"expression": js, "returnByValue": True})
print("Click result:", json.dumps(res, indent=2))

ws.close()

