(function() {
  function dig(root, results) {
    if (!root) return results;
    const all = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of all) {
      if (el.shadowRoot) dig(el.shadowRoot, results);
      const tag = el.tagName ? el.tagName.toLowerCase() : '';
      if (tag === 'controlled-radio-button' || tag === 'cr-radio-button' || tag === 'settings-radio-group') {
